INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('57298de5-d572-58db-97e9-d0d15d85651e', 'Portugal Resolution of the Assembly of the Republic', 'Resolution of the Assembly of the Republic no. 46/2009', 'Decreto-Lei n.º 158/2009 is a Portuguese law that establishes a new legal framework for the supervision of credit institutions and financial companies. The law aims to strengthen the stability and safety of the financial system by establishing a comprehensive and harmonized set of rules for the supervision and regulation of financial institutions. It establishes the Bank of Portugal as the main regulatory authority responsible for supervising financial institutions and outlines the various tools and procedures available to the regulatory authority to ensure compliance with the established rules and regulations. The law also introduces new provisions related to transparency and disclosure, risk management, and corporate governance in the financial sector.', 'Decreto-Lei n.º 158/2009 is a Portuguese law that establishes a new legal framework for the supervision of credit institutions and financial companies. The law aims to strengthen the stability and safety of the financial system by establishing a comprehensive and harmonized set of rules for the supervision and regulation of financial institutions. It establishes the Bank of Portugal as the main regulatory authority responsible for supervising financial institutions and outlines the various tools and procedures available to the regulatory authority to ensure compliance with the established rules and regulations. The law also introduces new provisions related to transparency and disclosure, risk management, and corporate governance in the financial sector.', 'Decreto-Lei n.º 158/2009 is a Portuguese law that establishes a new legal framework for the supervision of credit institutions and financial companies. The law aims to strengthen the stability and safety of the financial system by establishing a comprehensive and harmonized set of rules for the supervision and regulation of financial institutions. It establishes the Bank of Portugal as the main regulatory authority responsible for supervising financial institutions and outlines the various tools and procedures available to the regulatory authority to ensure compliance with the established rules and regulations. The law also introduces new provisions related to transparency and disclosure, risk management, and corporate governance in the financial sector.', 'Portugal', 'climate', 'in_force', '2009-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_24', ARRAY['portugal', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46271672-a4c2-516d-a480-8e1933f4bf48', 'Portugal Resolution of the Council of Ministers no', 'Resolution of the Council of Ministers no . 49/2007', 'With this resolution the Portuguese Government encourages all public companies of the business sector to develop a sustainability strategy and to adopt sustainability practices. Resolution of the Council of Ministers, N. º 49/2007, March 28th, approved the Principles of Good Governance of public companies, according to which companies are compelled to include in their annual Report and accounts a sustainability analysis in the corporate governance section. The aim is for these companies to implement corporate models with high levels of performance, contributing to the dissemination of good practices in the sustainability area, including the adoption of a sustainability strategy in the economic, environmental and social areas.', 'With this resolution the Portuguese Government encourages all public companies of the business sector to develop a sustainability strategy and to adopt sustainability practices. Resolution of the Council of Ministers, N. º 49/2007, March 28th, approved the Principles of Good Governance of public companies, according to which companies are compelled to include in their annual Report and accounts a sustainability analysis in the corporate governance section. The aim is for these companies to implement corporate models with high levels of performance, contributing to the dissemination of good practices in the sustainability area, including the adoption of a sustainability strategy in the economic, environmental and social areas.', 'With this resolution the Portuguese Government encourages all public companies of the business sector to develop a sustainability strategy and to adopt sustainability practices. Resolution of the Council of Ministers, N. º 49/2007, March 28th, approved the Principles of Good Governance of public companies, according to which companies are compelled to include in their annual Report and accounts a sustainability analysis in the corporate governance section. The aim is for these companies to implement corporate models with high levels of performance, contributing to the dissemination of good practices in the sustainability area, including the adoption of a sustainability strategy in the economic, environmental and social areas.', 'Portugal', 'climate', 'in_force', '2007-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_11', ARRAY['other sustainability policy', 'portugal', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('33906b77-1b6e-5ac1-864c-a00855902216', 'Portugal Corporate Governance Code', 'Corporate Governance Code, 2007', 'The Corporate Governance Code of 2007 is a set of guidelines developed by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code is based on internationally recognized principles and covers a range of topics, such as board composition and functioning, remuneration, and transparency. The code is not mandatory, but companies are expected to comply with it or explain why they have not done so. The code aims to increase transparency, accountability, and shareholder value, and to promote investor confidence in the Portuguese market. The code has been updated several times since its introduction in 2007.', 'The Corporate Governance Code of 2007 is a set of guidelines developed by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code is based on internationally recognized principles and covers a range of topics, such as board composition and functioning, remuneration, and transparency. The code is not mandatory, but companies are expected to comply with it or explain why they have not done so. The code aims to increase transparency, accountability, and shareholder value, and to promote investor confidence in the Portuguese market. The code has been updated several times since its introduction in 2007.', 'The Corporate Governance Code of 2007 is a set of guidelines developed by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code is based on internationally recognized principles and covers a range of topics, such as board composition and functioning, remuneration, and transparency. The code is not mandatory, but companies are expected to comply with it or explain why they have not done so. The code aims to increase transparency, accountability, and shareholder value, and to promote investor confidence in the Portuguese market. The code has been updated several times since its introduction in 2007.', 'Portugal', 'climate', 'in_force', '2007-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_13', ARRAY['portugal', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1b74b78f-1b19-5bd2-934e-fd348f0e49b2', 'Portugal Recommendations for Listed Companies', 'Recommendations for Listed Companies, 2006', 'The recommendations presented in this report mainly target listed companies but can also benefit non-listed companies with necessary adaptations. The improvement of corporate governance mechanisms is essential for optimizing corporate performance and protecting the interests of all participants in corporate life. The recommendations cover critical aspects of corporate governance such as the Board of Directors, General Meeting, external and internal audits, shareholders, institutional investors, and corporate conduct culture. The comply or explain principle is emphasized to allow companies to have legitimate freedom in their governance options. Legislative interventions may be necessary to implement some recommendations. Existing normative provisions are also identified alongside the text.', 'The recommendations presented in this report mainly target listed companies but can also benefit non-listed companies with necessary adaptations. The improvement of corporate governance mechanisms is essential for optimizing corporate performance and protecting the interests of all participants in corporate life. The recommendations cover critical aspects of corporate governance such as the Board of Directors, General Meeting, external and internal audits, shareholders, institutional investors, and corporate conduct culture. The comply or explain principle is emphasized to allow companies to have legitimate freedom in their governance options. Legislative interventions may be necessary to implement some recommendations. Existing normative provisions are also identified alongside the text.', 'The recommendations presented in this report mainly target listed companies but can also benefit non-listed companies with necessary adaptations. The improvement of corporate governance mechanisms is essential for optimizing corporate performance and protecting the interests of all participants in corporate life. The recommendations cover critical aspects of corporate governance such as the Board of Directors, General Meeting, external and internal audits, shareholders, institutional investors, and corporate conduct culture. The comply or explain principle is emphasized to allow companies to have legitimate freedom in their governance options. Legislative interventions may be necessary to implement some recommendations. Existing normative provisions are also identified alongside the text.', 'Portugal', 'climate', 'in_force', '2006-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_22', ARRAY['guidance_frameworks', 'portugal', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2f0b115d-32b4-5237-854d-a9215ec2a151', 'Portugal Decree-Law', 'Decree-Law No. 178/2006', 'Decreto-Lei n.º 1578/2006 is a Portuguese law that regulates the supervision and control of the financial and insurance sectors. The law establishes the legal framework for the supervision of credit institutions, insurance companies, and pension funds by the Portuguese Central Bank and the Portuguese Insurance and Pension Funds Supervisory Authority. The law sets out the criteria and procedures for the authorization, operation, and termination of financial and insurance entities, as well as their reporting requirements, prudential rules, and corporate governance standards. The law also provides for the establishment of a financial stability council to coordinate the macroprudential supervision of the financial system.', 'Decreto-Lei n.º 1578/2006 is a Portuguese law that regulates the supervision and control of the financial and insurance sectors. The law establishes the legal framework for the supervision of credit institutions, insurance companies, and pension funds by the Portuguese Central Bank and the Portuguese Insurance and Pension Funds Supervisory Authority. The law sets out the criteria and procedures for the authorization, operation, and termination of financial and insurance entities, as well as their reporting requirements, prudential rules, and corporate governance standards. The law also provides for the establishment of a financial stability council to coordinate the macroprudential supervision of the financial system.', 'Decreto-Lei n.º 1578/2006 is a Portuguese law that regulates the supervision and control of the financial and insurance sectors. The law establishes the legal framework for the supervision of credit institutions, insurance companies, and pension funds by the Portuguese Central Bank and the Portuguese Insurance and Pension Funds Supervisory Authority. The law sets out the criteria and procedures for the authorization, operation, and termination of financial and insurance entities, as well as their reporting requirements, prudential rules, and corporate governance standards. The law also provides for the establishment of a financial stability council to coordinate the macroprudential supervision of the financial system.', 'Portugal', 'climate', 'in_force', '2006-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_28', ARRAY['other sustainability policy', 'portugal', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('73f453dc-b59c-586a-9cee-9ab7c6fc2a65', 'Portugal CMVM Regulation (Amends CMVM Regulations and on Corporate', 'CMVM Regulation No. 10/2005 (Amends CMVM Regulations No. 7/2001 and No. 4/2004 on Corporate Governance and Information Duties)', 'Regulamento da CMVM n.o 10/2005 is a regulatory document that modifies two existing regulations, namely Regulamento da CMVM no 7/2001 and Regulamento da CMVM no 4/2004. The changes relate to corporate governance and disclosure requirements for companies. The amendments introduced new provisions regarding the responsibilities of directors, the composition and functioning of audit committees, and the disclosure of information to shareholders. The goal of these changes is to enhance transparency and accountability in corporate governance and to provide investors with more reliable information about the companies in which they invest. The amendments apply to all companies listed on the Portuguese stock exchange and aim to strengthen investor protection and confidence in the market.', 'Regulamento da CMVM n.o 10/2005 is a regulatory document that modifies two existing regulations, namely Regulamento da CMVM no 7/2001 and Regulamento da CMVM no 4/2004. The changes relate to corporate governance and disclosure requirements for companies. The amendments introduced new provisions regarding the responsibilities of directors, the composition and functioning of audit committees, and the disclosure of information to shareholders. The goal of these changes is to enhance transparency and accountability in corporate governance and to provide investors with more reliable information about the companies in which they invest. The amendments apply to all companies listed on the Portuguese stock exchange and aim to strengthen investor protection and confidence in the market.', 'Regulamento da CMVM n.o 10/2005 is a regulatory document that modifies two existing regulations, namely Regulamento da CMVM no 7/2001 and Regulamento da CMVM no 4/2004. The changes relate to corporate governance and disclosure requirements for companies. The amendments introduced new provisions regarding the responsibilities of directors, the composition and functioning of audit committees, and the disclosure of information to shareholders. The goal of these changes is to enhance transparency and accountability in corporate governance and to provide investors with more reliable information about the companies in which they invest. The amendments apply to all companies listed on the Portuguese stock exchange and aim to strengthen investor protection and confidence in the market.', 'Portugal', 'climate', 'in_force', '2005-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_10', ARRAY['other sustainability policy', 'portugal', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4b202c3f-c3fa-50bb-a255-833c6f054093', 'Portugal Resolution of the Council of Ministers', 'Resolution of the Council of Ministers No. 113/2005', 'Resolution of the Council of Ministers No. 113/2005 is a Portuguese government resolution that aimed to promote the improvement of corporate governance practices in the country. The resolution created a national program for corporate governance, which included several measures to promote transparency, accountability, and fairness in the corporate sector. The program''s main objectives were to promote good governance practices in listed companies, improve the quality of financial information provided by companies, strengthen the role of auditors, and encourage the participation of shareholders in corporate decision-making. The resolution also called for the adoption of a corporate governance code by companies listed on the Portuguese stock exchange.', 'Resolution of the Council of Ministers No. 113/2005 is a Portuguese government resolution that aimed to promote the improvement of corporate governance practices in the country. The resolution created a national program for corporate governance, which included several measures to promote transparency, accountability, and fairness in the corporate sector. The program''s main objectives were to promote good governance practices in listed companies, improve the quality of financial information provided by companies, strengthen the role of auditors, and encourage the participation of shareholders in corporate decision-making. The resolution also called for the adoption of a corporate governance code by companies listed on the Portuguese stock exchange.', 'Resolution of the Council of Ministers No. 113/2005 is a Portuguese government resolution that aimed to promote the improvement of corporate governance practices in the country. The resolution created a national program for corporate governance, which included several measures to promote transparency, accountability, and fairness in the corporate sector. The program''s main objectives were to promote good governance practices in listed companies, improve the quality of financial information provided by companies, strengthen the role of auditors, and encourage the participation of shareholders in corporate decision-making. The resolution also called for the adoption of a corporate governance code by companies listed on the Portuguese stock exchange.', 'Portugal', 'climate', 'in_force', '2005-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_27', ARRAY['other sustainability policy', 'portugal', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('78a0e39d-e1b9-598a-974b-23e2768cbbef', 'Portugal Decree-Law', 'Decree-Law No. 233/2004', 'Decree-Law No. 233/2004 is a legal framework in Portugal that establishes the regime of transparency for public companies and their subsidiaries. It aims to ensure the transparency and accuracy of information that is provided to the market and investors by these companies. The law sets out requirements for financial reporting, disclosure of information, and communication with shareholders. It also provides guidelines for insider trading, related party transactions, and corporate governance. This law was an important step in promoting transparency and accountability in the Portuguese market, and it helped to align Portugal''s legal framework with international standards.', 'Decree-Law No. 233/2004 is a legal framework in Portugal that establishes the regime of transparency for public companies and their subsidiaries. It aims to ensure the transparency and accuracy of information that is provided to the market and investors by these companies. The law sets out requirements for financial reporting, disclosure of information, and communication with shareholders. It also provides guidelines for insider trading, related party transactions, and corporate governance. This law was an important step in promoting transparency and accountability in the Portuguese market, and it helped to align Portugal''s legal framework with international standards.', 'Decree-Law No. 233/2004 is a legal framework in Portugal that establishes the regime of transparency for public companies and their subsidiaries. It aims to ensure the transparency and accuracy of information that is provided to the market and investors by these companies. The law sets out requirements for financial reporting, disclosure of information, and communication with shareholders. It also provides guidelines for insider trading, related party transactions, and corporate governance. This law was an important step in promoting transparency and accountability in the Portuguese market, and it helped to align Portugal''s legal framework with international standards.', 'Portugal', 'climate', 'in_force', '2004-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_26', ARRAY['other sustainability policy', 'portugal', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('55dad699-1dd0-56c9-ba8b-1bab31179c3d', 'Portugal Accounting Guidelines Environmental Matters', 'Accounting Guidelines No. 29 Environmental Matters', 'Directriz contabilistica N 29 Matéria Ambientais 2004 is a set of guidelines issued by the Portuguese Accounting and Auditing Standards Board (CNC) in 2004. The guidelines provide guidance for companies on how to account for and disclose environmental matters in their financial statements. The purpose of these guidelines is to promote transparency and accountability in relation to environmental issues. The adoption of the Directriz contabilistica N 29 Matéria Ambientais 2004 is voluntary, but companies that choose to adopt the guidelines are expected to comply with all of its requirements.', 'Directriz contabilistica N 29 Matéria Ambientais 2004 is a set of guidelines issued by the Portuguese Accounting and Auditing Standards Board (CNC) in 2004. The guidelines provide guidance for companies on how to account for and disclose environmental matters in their financial statements. The purpose of these guidelines is to promote transparency and accountability in relation to environmental issues. The adoption of the Directriz contabilistica N 29 Matéria Ambientais 2004 is voluntary, but companies that choose to adopt the guidelines are expected to comply with all of its requirements.', 'Directriz contabilistica N 29 Matéria Ambientais 2004 is a set of guidelines issued by the Portuguese Accounting and Auditing Standards Board (CNC) in 2004. The guidelines provide guidance for companies on how to account for and disclose environmental matters in their financial statements. The purpose of these guidelines is to promote transparency and accountability in relation to environmental issues. The adoption of the Directriz contabilistica N 29 Matéria Ambientais 2004 is voluntary, but companies that choose to adopt the guidelines are expected to comply with all of its requirements.', 'Portugal', 'climate', 'in_force', '2004-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_4', ARRAY['guidance_frameworks', 'portugal', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b0a17f98-f8ba-514f-b292-acf5f99a3eec', 'Portugal CMVM Corporate Governance Code 2010 (Recommendations)', 'CMVM Corporate Governance Code 2010 (Recommendations)', 'The Regulation amending Regulation 7/2001 and Regulation 11/2000 is a set of amendments issued by the Portuguese Securities Market Commission (CMVM) to update and enhance the Corporate Governance rules for companies listed on the Portuguese stock exchange. The amendments cover topics such as board composition, independence, and evaluation, remuneration, audit committees, risk management, and shareholder rights. The amendments aim to align the rules with international best practices and enhance transparency, accountability, and shareholder value. The amended regulations are mandatory, and companies are required to comply with the new provisions. The changes reflect the evolving nature of corporate governance and the importance of effective governance in the modern business landscape.', 'The Regulation amending Regulation 7/2001 and Regulation 11/2000 is a set of amendments issued by the Portuguese Securities Market Commission (CMVM) to update and enhance the Corporate Governance rules for companies listed on the Portuguese stock exchange. The amendments cover topics such as board composition, independence, and evaluation, remuneration, audit committees, risk management, and shareholder rights. The amendments aim to align the rules with international best practices and enhance transparency, accountability, and shareholder value. The amended regulations are mandatory, and companies are required to comply with the new provisions. The changes reflect the evolving nature of corporate governance and the importance of effective governance in the modern business landscape.', 'The Regulation amending Regulation 7/2001 and Regulation 11/2000 is a set of amendments issued by the Portuguese Securities Market Commission (CMVM) to update and enhance the Corporate Governance rules for companies listed on the Portuguese stock exchange. The amendments cover topics such as board composition, independence, and evaluation, remuneration, audit committees, risk management, and shareholder rights. The amendments aim to align the rules with international best practices and enhance transparency, accountability, and shareholder value. The amended regulations are mandatory, and companies are required to comply with the new provisions. The changes reflect the evolving nature of corporate governance and the importance of effective governance in the modern business landscape.', 'Portugal', 'climate', 'in_force', '2003-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_17', ARRAY['guidance_frameworks', 'portugal', 'sdg16', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6547c650-4b82-5618-8db6-9e0b3cb10902', 'Portugal Recommendations on Corporate Governance', 'Recommendations on Corporate Governance, 2003', 'The Corporate Governance Code of 2003 is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code covers topics such as board composition and functioning, remuneration, audit committees, risk management, shareholder rights, and disclosure of information. The code is based on internationally recognized principles and aims to enhance transparency, accountability, and shareholder value. While the code is not mandatory, companies are encouraged to adopt its recommendations to promote investor confidence and ensure the long-term success of their business. The code has been updated several times since its introduction in 2003 to reflect changes in best practices and market conditions.', 'The Corporate Governance Code of 2003 is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code covers topics such as board composition and functioning, remuneration, audit committees, risk management, shareholder rights, and disclosure of information. The code is based on internationally recognized principles and aims to enhance transparency, accountability, and shareholder value. While the code is not mandatory, companies are encouraged to adopt its recommendations to promote investor confidence and ensure the long-term success of their business. The code has been updated several times since its introduction in 2003 to reflect changes in best practices and market conditions.', 'The Corporate Governance Code of 2003 is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code covers topics such as board composition and functioning, remuneration, audit committees, risk management, shareholder rights, and disclosure of information. The code is based on internationally recognized principles and aims to enhance transparency, accountability, and shareholder value. While the code is not mandatory, companies are encouraged to adopt its recommendations to promote investor confidence and ensure the long-term success of their business. The code has been updated several times since its introduction in 2003 to reflect changes in best practices and market conditions.', 'Portugal', 'climate', 'in_force', '2003-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_21', ARRAY['guidance_frameworks', 'portugal', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
