INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b4a3c900-8e1f-534c-92f4-b061a786064d', 'Portugal Recommendations on Corporate Governance', 'Recommendations on Corporate Governance, 1999', 'The Recommendations on Corporate Governance of 1999 were issued by the Portuguese Securities Market Commission (CMVM) to encourage good corporate governance practices among companies listed on the Portuguese stock exchange. The recommendations cover topics such as board composition and functioning, remuneration, audit committees, risk management, shareholder rights, and disclosure of information. The recommendations are voluntary and companies are encouraged to adopt them as a guide to good corporate governance practices. The recommendations aim to promote transparency, accountability, and shareholder value and have been updated over time to reflect changes in best practices and market conditions.', 'The Recommendations on Corporate Governance of 1999 were issued by the Portuguese Securities Market Commission (CMVM) to encourage good corporate governance practices among companies listed on the Portuguese stock exchange. The recommendations cover topics such as board composition and functioning, remuneration, audit committees, risk management, shareholder rights, and disclosure of information. The recommendations are voluntary and companies are encouraged to adopt them as a guide to good corporate governance practices. The recommendations aim to promote transparency, accountability, and shareholder value and have been updated over time to reflect changes in best practices and market conditions.', 'The Recommendations on Corporate Governance of 1999 were issued by the Portuguese Securities Market Commission (CMVM) to encourage good corporate governance practices among companies listed on the Portuguese stock exchange. The recommendations cover topics such as board composition and functioning, remuneration, audit committees, risk management, shareholder rights, and disclosure of information. The recommendations are voluntary and companies are encouraged to adopt them as a guide to good corporate governance practices. The recommendations aim to promote transparency, accountability, and shareholder value and have been updated over time to reflect changes in best practices and market conditions.', 'Portugal', 'climate', 'in_force', '1999-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_20', ARRAY['guidance_frameworks', 'portugal', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7756e42e-f8f4-5ee5-8ed0-da4b05dbc23e', 'Qatar Law No. (8) of 2021 Amending Some Provisions', 'Law No. (8) of 2021 Amending Some Provisions of Law No. (11) of 2015 Promulgating the Commercial Companies Law', 'The Commercial Companies Law Amendments (2021) introduce significant reforms to corporate governance, transparency, and shareholder rights in Qatar. These amendments align with international best practices and enhance the regulatory framework for businesses operating in Qatar.

Key provisions include:

Corporate Governance Reforms:
The Minister of Commerce and Industry is responsible for setting governance rules for private shareholding companies.
The Qatar Financial Markets Authority (QFMA) oversees governance for listed companies.
Board of Directors & Shareholder Rights:
Companies must ensure board diversity and independent representation.
Minority shareholders receive additional protections, including representation rights.
Electronic voting at general assemblies is introduced.
Disclosure & Transparency:
Board members must disclose conflicts of interest and related-party transactions.
Companies must provide detailed financial statements, director remuneration reports, and donation disclosures.
Anti-Corruption & Fair Business Practices:
Board members and executives cannot engage in business that competes with their company without prior approval.
Companies must disclose transactions exceeding 10% of their net assets.
Regulatory Oversight & Enforcement:
Stricter penalties for non-compliance, including fines and disqualification of board members.
Strengthened AML/CFT (Anti-Money Laundering and Counter-Terrorism Financing) requirements.
These amendments improve corporate accountability, financial integrity, and investor protection in Qatar’s business environment.', 'The Commercial Companies Law Amendments (2021) introduce significant reforms to corporate governance, transparency, and shareholder rights in Qatar. These amendments align with international best practices and enhance the regulatory framework for businesses operating in Qatar.

