INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('afff2644-89e2-50fa-a363-2783373aa1f7', 'Romania Law Of 15 November 2011 On The Regime', 'Law No. 211 Of 15 November 2011 On The Regime For Waste', 'This law shall determine the measures necessary for the protection of the environment and public health by prevening or reducing the adverse effects arising from the generation and management of waste by reducing the effets of the use of redources and increasing the efficiency of their use.', 'This law shall determine the measures necessary for the protection of the environment and public health by prevening or reducing the adverse effects arising from the generation and management of waste by reducing the effets of the use of redources and increasing the efficiency of their use.', 'This law shall determine the measures necessary for the protection of the environment and public health by prevening or reducing the adverse effects arising from the generation and management of waste by reducing the effets of the use of redources and increasing the efficiency of their use.', 'Romania', 'circularity', 'in_force', '2011-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_11', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'sdg3', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('664a424d-6420-5279-858e-82e57ce1caf4', 'Romania Emergency Ordinance of November 30, 2011 on corporate', 'Emergency Ordinance No. 109/2011 of November 30, 2011 on corporate governance of public enterprises', 'This document is a government Emergency Ordinance no. 109/2011, published in the Official Gazette of Romania, Part I, no. 883 of December 14, 2011.', 'This document is a government Emergency Ordinance no. 109/2011, published in the Official Gazette of Romania, Part I, no. 883 of December 14, 2011.', 'This document is a government Emergency Ordinance no. 109/2011, published in the Official Gazette of Romania, Part I, no. 883 of December 14, 2011.', 'Romania', 'governance', 'in_force', '2011-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_13', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('03e5b70b-697c-5b5b-8a5c-83a75b4112e5', 'Romania Emergency Ordinance of November 30, 2011 on corporate', 'Emergency Ordinance no. 109 of November 30, 2011 on corporate governance of public enterprises', 'This emergency ordinance applies to public enterprises, Romanian legal entities. The provisions of this emergency ordinance shall also apply to the following public enterprises: a) financial institutions and financial investment service companies and investment management companies provided by Government Emergency Ordinance no. 99/2006 on credit institutions and capital adequacy, approved with amendments and completions by Law no. 227/2007, with subsequent amendments and completions; b) the companies whose activity is regulated by Law no. 32/2000 on the activity and supervision of insurance and reinsurance intermediaries, with subsequent amendments and completions.', 'This emergency ordinance applies to public enterprises, Romanian legal entities. The provisions of this emergency ordinance shall also apply to the following public enterprises: a) financial institutions and financial investment service companies and investment management companies provided by Government Emergency Ordinance no. 99/2006 on credit institutions and capital adequacy, approved with amendments and completions by Law no. 227/2007, with subsequent amendments and completions; b) the companies whose activity is regulated by Law no. 32/2000 on the activity and supervision of insurance and reinsurance intermediaries, with subsequent amendments and completions.', 'This emergency ordinance applies to public enterprises, Romanian legal entities. The provisions of this emergency ordinance shall also apply to the following public enterprises: a) financial institutions and financial investment service companies and investment management companies provided by Government Emergency Ordinance no. 99/2006 on credit institutions and capital adequacy, approved with amendments and completions by Law no. 227/2007, with subsequent amendments and completions; b) the companies whose activity is regulated by Law no. 32/2000 on the activity and supervision of insurance and reinsurance intermediaries, with subsequent amendments and completions.', 'Romania', 'climate', 'in_force', '2011-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_2', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg16', 'sdg9', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('251966bd-7201-5c23-8877-843f33c0404f', 'Romania Bucharest Stock Exchange Corporate Governance Code', 'Bucharest Stock Exchange Corporate Governance Code - 2009', 'The present Code contains certain recommendations that are supplementary provisions to legal obligation under the laws of Romania (e.g. Companies Act, the Accounting Act, the Capital Market Act, etc.).', 'The present Code contains certain recommendations that are supplementary provisions to legal obligation under the laws of Romania (e.g. Companies Act, the Accounting Act, the Capital Market Act, etc.).', 'The present Code contains certain recommendations that are supplementary provisions to legal obligation under the laws of Romania (e.g. Companies Act, the Accounting Act, the Capital Market Act, etc.).', 'Romania', 'governance', 'in_force', '2008-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_10', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('df0660b9-9a49-534a-b289-bcf5880bf697', 'Romania Rulebook of the Bucharest Stock Exchange', 'Rulebook of the Bucharest Stock Exchange', 'This document is the 2007 version of the Bucharest Stock Exchange Rulebook.', 'This document is the 2007 version of the Bucharest Stock Exchange Rulebook.', 'This document is the 2007 version of the Bucharest Stock Exchange Rulebook.', 'Romania', 'governance', 'in_force', '2007-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_12', ARRAY['disclosure', 'mandatory', 'mandatory_regulations', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('33c50887-5e2d-5e68-ae42-f1c816c36b58', 'Romania Government Decision on environmental impact assessments', 'Government Decision No. 1213/2006 on environmental impact assessments', 'Projects that are likely to have significant environmental effects are required to produce an environmental impact assessment. These projects may have an impact due to their nature, size or location, and are listed in Annex 2. Article 12 stipulates that all projects required to produce an environmental impact assessment are also required to provide a report using the information outlined in Annex 4. The information provided should include a description of the project, an assessment of the main effects of the project, and a description of the measures envisaged to reduce or avoid environmental damage.', 'Projects that are likely to have significant environmental effects are required to produce an environmental impact assessment. These projects may have an impact due to their nature, size or location, and are listed in Annex 2. Article 12 stipulates that all projects required to produce an environmental impact assessment are also required to provide a report using the information outlined in Annex 4. The information provided should include a description of the project, an assessment of the main effects of the project, and a description of the measures envisaged to reduce or avoid environmental damage.', 'Projects that are likely to have significant environmental effects are required to produce an environmental impact assessment. These projects may have an impact due to their nature, size or location, and are listed in Annex 2. Article 12 stipulates that all projects required to produce an environmental impact assessment are also required to provide a report using the information outlined in Annex 4. The information provided should include a description of the project, an assessment of the main effects of the project, and a description of the measures envisaged to reduce or avoid environmental damage.', 'Romania', 'climate', 'in_force', '2006-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_14', ARRAY['regulations', 'mandatory', 'disclosure', 'sdg15', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ed4092d1-0884-5216-9a29-de55af01ccc6', 'Romania Law of July 14, 2006 on occupational safety', 'Law no. 319 of July 14, 2006 on occupational safety and health', 'Article 12 of this Law stipulates that employers shall keep a record of all incidents that result in work incapacity of three days or more, including work accidents and hazardous incidents. The Minister of Labor, Social Solidarity and Family will determine the timing of the production of these documents to the Authority, depending on the size and character of the activity or project.', 'Article 12 of this Law stipulates that employers shall keep a record of all incidents that result in work incapacity of three days or more, including work accidents and hazardous incidents. The Minister of Labor, Social Solidarity and Family will determine the timing of the production of these documents to the Authority, depending on the size and character of the activity or project.', 'Article 12 of this Law stipulates that employers shall keep a record of all incidents that result in work incapacity of three days or more, including work accidents and hazardous incidents. The Minister of Labor, Social Solidarity and Family will determine the timing of the production of these documents to the Authority, depending on the size and character of the activity or project.', 'Romania', 'social', 'in_force', '2006-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_17', ARRAY['sdg8', 'regulations', 'mandatory', 'sdg12', 'disclosure', 'sdg3', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1301f39f-0b77-5e18-bbfe-749fca881608', 'Romania Decision of July 28, 2005 on public access', 'Decision no. 878/2005 of July 28, 2005 on public access to environmental information', 'The present decision ensures the right of access to the information regarding the environment held by or for the public authorities and establishes the conditions, the basic terms and the modalities of exercising this right.', 'The present decision ensures the right of access to the information regarding the environment held by or for the public authorities and establishes the conditions, the basic terms and the modalities of exercising this right.', 'The present decision ensures the right of access to the information regarding the environment held by or for the public authorities and establishes the conditions, the basic terms and the modalities of exercising this right.', 'Romania', 'governance', 'in_force', '2005-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_9', ARRAY['mandatory', 'other sustainability policy', 'mandatory_regulations', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d4be1ec1-33a8-5701-95fd-0911b24b15a9', 'Romania Law of July 18, 2001 for the approval', 'Law no. 451 of July 18, 2001 for the approval of the Government Emergency Ordinance no. 200/2000 on the classification, labeling and packaging of dangerous chemical substances and preparations', 'This Law amends and approves the Ordinance of the Government 200/2000 on the classification, labelling and packaging of chemical substances and dangerous goods. Article 19 of this Law amends Article 24 of the Ordinance and requires that all manufacturers and importers of chemical or dangerous substances provide the National Agency for Dangerous Chemical Substances with all the information of the properties of those substances that may harm human or environmental health.', 'This Law amends and approves the Ordinance of the Government 200/2000 on the classification, labelling and packaging of chemical substances and dangerous goods. Article 19 of this Law amends Article 24 of the Ordinance and requires that all manufacturers and importers of chemical or dangerous substances provide the National Agency for Dangerous Chemical Substances with all the information of the properties of those substances that may harm human or environmental health.', 'This Law amends and approves the Ordinance of the Government 200/2000 on the classification, labelling and packaging of chemical substances and dangerous goods. Article 19 of this Law amends Article 24 of the Ordinance and requires that all manufacturers and importers of chemical or dangerous substances provide the National Agency for Dangerous Chemical Substances with all the information of the properties of those substances that may harm human or environmental health.', 'Romania', 'climate', 'in_force', '2001-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_16', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg3', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('44aee88e-f8cc-51b1-8e3a-2315a7d8c1a5', 'Corporate Governance Initiative for Economic Democracy in Romania', 'Corporate Governance Initiative for Economic Democracy in Romania', 'Starting from the principle of observing and strengthening private property rights, this Code provides a set of rules and standards to guide the management of a company with respect to its strategic planning and decision making, in order to promote the interests of shareholders and associates, creditors, customers, employers and employees.
This Code is not concerned with the general rules which define business ethics, either with respect to the relationship between companies or with respect to the ethical obligations of the employees of a company.', 'Starting from the principle of observing and strengthening private property rights, this Code provides a set of rules and standards to guide the management of a company with respect to its strategic planning and decision making, in order to promote the interests of shareholders and associates, creditors, customers, employers and employees.
This Code is not concerned with the general rules which define business ethics, either with respect to the relationship between companies or with respect to the ethical obligations of the employees of a company.', 'Starting from the principle of observing and strengthening private property rights, this Code provides a set of rules and standards to guide the management of a company with respect to its strategic planning and decision making, in order to promote the interests of shareholders and associates, creditors, customers, employers and employees.
This Code is not concerned with the general rules which define business ethics, either with respect to the relationship between companies or with respect to the ethical obligations of the employees of a company.', 'Romania', 'governance', 'in_force', '2000-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_8', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1a1a45b2-47b8-5c45-9a95-b7ecfac1dd17', 'Romania Decision of March 8, 1999 for the introduction', 'Decision no. 155 of March 8, 1999 for the introduction of the waste management record and the European Waste Catalog', 'This Regulation requires that all businesses and other waste producers, except those involved in the management of household waste, to maintain a waste management record. The Annex of the Regulation provides the forms and metric that should be used by those producing a waste management record. The Regulation also stipulates the consequences and fines that result from the submission of incorrect information, late submission or failure to submit.', 'This Regulation requires that all businesses and other waste producers, except those involved in the management of household waste, to maintain a waste management record. The Annex of the Regulation provides the forms and metric that should be used by those producing a waste management record. The Regulation also stipulates the consequences and fines that result from the submission of incorrect information, late submission or failure to submit.', 'This Regulation requires that all businesses and other waste producers, except those involved in the management of household waste, to maintain a waste management record. The Annex of the Regulation provides the forms and metric that should be used by those producing a waste management record. The Regulation also stipulates the consequences and fines that result from the submission of incorrect information, late submission or failure to submit.', 'Romania', 'circularity', 'in_force', '1999-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_15', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c097d2a1-4d2e-5adf-958b-a679451a38c8', 'Romania Order of March 19, 1996 for the approval', 'Order no. 125 of March 19, 1996 for the approval of the Procedure for the regulation of economic and social activities with an impact on the environment', 'Owners of projects or activities that might have an environmental impact (as listed in Annex 2) are required to complete an environmental impact assessment using the methodology outlined in Annex 4. Once the assessment is complete, the owner of the project or activity is required to prepare and submit an environmental impact assessment report to the Environmental Protection Agency. The minimum content for the report is described in Annex 5, and includes a description of the project or activity, the sources of pollutants, the environment or population potentially affected, an assessment of the risk of major accidents, and recommendations to mitigate or improve the project to prevent environmental damage.', 'Owners of projects or activities that might have an environmental impact (as listed in Annex 2) are required to complete an environmental impact assessment using the methodology outlined in Annex 4. Once the assessment is complete, the owner of the project or activity is required to prepare and submit an environmental impact assessment report to the Environmental Protection Agency. The minimum content for the report is described in Annex 5, and includes a description of the project or activity, the sources of pollutants, the environment or population potentially affected, an assessment of the risk of major accidents, and recommendations to mitigate or improve the project to prevent environmental damage.', 'Owners of projects or activities that might have an environmental impact (as listed in Annex 2) are required to complete an environmental impact assessment using the methodology outlined in Annex 4. Once the assessment is complete, the owner of the project or activity is required to prepare and submit an environmental impact assessment report to the Environmental Protection Agency. The minimum content for the report is described in Annex 5, and includes a description of the project or activity, the sources of pollutants, the environment or population potentially affected, an assessment of the risk of major accidents, and recommendations to mitigate or improve the project to prevent environmental damage.', 'Romania', 'climate', 'in_force', '1996-01-01'::date, 'Romania', 'https://www.carrotsandsticks.org/policies/149_18', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'romania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('367df43b-ca7c-5ed2-9ba2-465d65a55dd1', 'Decree of the Government of the Russian Federation', 'Decree of the Government of the Russian Federation dated 21.09.2021
